style.css:
/* === Book-like theme for Grok chat (grok.com / x.com) === */

/* Overall page background - old paper / parchment feel */
body, html, [class*="min-h-screen"], [class*="bg-"] {
    background-color: #f5f5dc !important; /* Beige parchment */
    background-image: linear-gradient(rgba(0,0,0,0.02) 1px, transparent 1px),
                      linear-gradient(90deg, rgba(0,0,0,0.02) 1px, transparent 1px) !important;
    background-size: 20px 20px !important; /* Subtle paper texture grid */
    color: #2c1b0f !important; /* Dark sepia text */
}

/* Main chat container - center it like a book page with max width */
div[class*="max-w-"], div[class*="mx-auto"], main, [role="main"], [class*="container"] {
    max-width: 800px !important; /* Classic book page width */
    margin: 0 auto !important;
    padding: 40px 60px !important; /* Generous book margins */
    background: #fffef7 !important; /* Off-white page */
    box-shadow: 0 0 25px rgba(0,0,0,0.15), 
                10px 0 30px rgba(0,0,0,0.08),
                -10px 0 30px rgba(0,0,0,0.08) !important; /* Page shadow effect */
    border: 1px solid #d4c9a8 !important;
    border-radius: 4px !important;
}

/* Message bubbles / chat items */
div[class*="flex"], div[class*="items-start"], div[class*="gap-"], article, [data-message-author] {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 1.2em 0 !important;
    margin: 1.5em 0 !important;
    border-bottom: 1px solid #e0d8c3 !important; /* Subtle page line separator */
}

/* User & Grok messages - indent like paragraphs, serif font */
div[class*="prose"], p, div[class*="text-"], [class*="leading-"] {
    font-family: Georgia, "Times New Roman", Times, serif !important;
    font-size: 19px !important;
    line-height: 1.68 !important; /* Classic book leading */
    color: #2f1e0e !important;
}

/* Make Grok's responses look like narrative text */
div[class*="prose"] > p, div[class*="whitespace-pre-wrap"] {
    text-indent: 1.5em !important; /* First-line indent like a book paragraph */
    margin: 0 0 1.2em 0 !important;
}

/* Headers / titles in responses */
h1, h2, h3, [class*="text-2xl"], [class*="font-bold"] {
    font-family: "Georgia", serif !important;
    color: #3c2a1a !important;
    margin: 1.8em 0 0.8em !important;
}

/* Input area - make it look like a writing page */
textarea, div[contenteditable="true"], [class*="border"], [class*="focus:"] {
    background: #fffef7 !important;
    border: 1px solid #c0b090 !important;
    border-radius: 6px !important;
    font-family: Georgia, serif !important;
    font-size: 18px !important;
    padding: 18px !important;
    box-shadow: inset 0 2px 6px rgba(0,0,0,0.06) !important;
}

/* Hide or minimize distracting elements (sidebar, header, etc.) */
nav, header, footer, [class*="fixed"], [aria-label="sidebar"], [class*="top-0"] {
    display: none !important; /* Or opacity: 0.3 !important; for semi-hidden */
}

